// Expected values generated by the unchanged Python phash implementation.
#[test]
fn textured_rgb_matches_python_in_all_modes() {
    let im = image::RgbImage::from_fn(100, 150, |x, y| {
        image::Rgb([
            ((x * 17 + y * 3) % 256) as u8,
            ((x * 7 + y * 19) % 256) as u8,
            ((x * 11 + y * 13) % 256) as u8,
        ])
    });
    assert_eq!(
        mdript_core::artwork_hash(&im, [0, 0, 100, 150], false, false).unwrap(),
        "a64fa40d5af15c7185f6a40e5a4451ff"
    );
    assert_eq!(
        mdript_core::artwork_hash(&im, [0, 0, 100, 150], true, false).unwrap(),
        "a64fa40d5af15c71"
    );
    assert_eq!(
        mdript_core::artwork_hash(&im, [0, 0, 100, 150], false, true).unwrap(),
        "a64fa40d5af15c7185f6a40e5a4451ff86883f644e5b527e"
    );
}
